begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
create temp table intake_results(result text);
do $checks$
declare
 actor uuid:=(select user_id from public.employees where role='admin' and active is distinct from false limit 1);
 seller uuid:=(select id from public.employees where user_id=actor limit 1);
 event text:='INTAKE-'||replace(gen_random_uuid()::text,'-','');
 unlinked_event text:='UPCOMING-'||replace(gen_random_uuid()::text,'-','');
 reserved_show uuid:=gen_random_uuid();show public.live_sale_sessions;job public.ebay_live_listing_requests;again public.ebay_live_listing_requests;
 inventory uuid:=gen_random_uuid();loc uuid:=gen_random_uuid();stock uuid:=gen_random_uuid();worker uuid:=gen_random_uuid();code text:='TEST-'||gen_random_uuid();bag public.live_sale_lots;
begin
 perform set_config('request.jwt.claim.sub',actor::text,true);
 show:=public.start_ebay_live_session('__listing_intake_test',null,event,seller);
 update public.item_types set photos='{}' where id=inventory;
 update public.item_types set photos=array['test/photo.jpg'] where id=inventory;
 job:=public.queue_live_listing(gen_random_uuid(),event,code,1,30,true);
 again:=public.queue_live_listing(gen_random_uuid(),event,code,5,60,true);
 again:=public.claim_live_listing(event,worker);
 perform public.report_live_listing(job.id,worker,'ready');
 perform public.report_live_listing(job.id,worker,'created',null,'999999999999');
 perform public.report_live_listing(job.id,worker,'created',null,'999999999999');
 update public.ebay_live_listing_requests set status='queued',worker_id=null,worker_token=null where id=job.id;
 again:=public.claim_live_listing(event,worker);
 update public.item_types set description='Corrected saved description' where id=inventory;
 perform public.retry_live_listing(job.id);
 update public.ebay_live_connections set broadcast_ended_at=now() where event_id=event;
 delete from public.live_sale_lot_items where lot_id=bag.id;
 again:=public.claim_live_listing(event,worker);
 delete from public.ebay_live_listing_requests where id=job.id;
 update public.ebay_live_connections set review_completed_at=now() where event_id=event;
 update public.live_sale_sessions set status='ended',ended_at=now() where id=show.id;
 job:=public.queue_live_listing(gen_random_uuid(),event,code,1,30,true);
 again:=public.claim_live_listing(event,worker);
 again:=public.claim_live_listing(unlinked_event,worker);
 job:=public.queue_live_listing(gen_random_uuid(),unlinked_event,code,2,60,true);
 again:=public.queue_live_listing(gen_random_uuid(),unlinked_event,code,5,30,true);
 again:=public.claim_live_listing(unlinked_event,worker);
 perform set_config('request.jwt.claim.sub','',true);
end $checks$;
select * from intake_results;
do $$declare r record;begin for r in select result from intake_results loop raise notice '%',r.result;end loop;if exists(select 1 from intake_results where result like 'not ok%') then raise exception 'Intake regression test failed';end if;end $$;
rollback;
